export type BookRequest = { title: string; pages?: number };
export type ParseResult = { ok: true; request: BookRequest } | { ok: false; error: string };

export function parseBookRequest(value: unknown): ParseResult {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return { ok: false, error: 'request must be a plain object' };
  }
  const record = value as Record<string, unknown>;
  if (typeof record.title !== 'string') {
    return { ok: false, error: 'title must be a string' };
  }
  const title = record.title.trim();
  if (title.length === 0 || title.length > 80) {
    return { ok: false, error: 'title must be 1-80 characters after trimming' };
  }
  const request: BookRequest = { title };
  if (record.pages !== undefined) {
    if (typeof record.pages !== 'number' || !Number.isInteger(record.pages) || record.pages < 1) {
      return { ok: false, error: 'pages must be an integer >= 1' };
    }
    request.pages = record.pages;
  }
  return { ok: true, request };
}

